PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS MaterialTypes (Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE, LossPercent REAL NOT NULL CHECK(LossPercent >= 0 AND LossPercent < 100));
CREATE TABLE IF NOT EXISTS Units (Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS ProductTypes (Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE, Coefficient REAL NOT NULL CHECK(Coefficient > 0));
CREATE TABLE IF NOT EXISTS Materials (Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE CHECK(length(trim(Name))>0), MaterialTypeId INTEGER NOT NULL REFERENCES MaterialTypes(Id), UnitId INTEGER NOT NULL REFERENCES Units(Id), PriceCents INTEGER NOT NULL CHECK(PriceCents>=0), Stock REAL NOT NULL CHECK(Stock>=0), Minimum REAL NOT NULL CHECK(Minimum>=0), PackageQuantity REAL NOT NULL CHECK(PackageQuantity>0));
CREATE TABLE IF NOT EXISTS Products (Id INTEGER PRIMARY KEY, Article TEXT NOT NULL UNIQUE, ProductTypeId INTEGER NOT NULL REFERENCES ProductTypes(Id), Name TEXT NOT NULL UNIQUE, MinimumPriceCents INTEGER NOT NULL CHECK(MinimumPriceCents>=0));
CREATE TABLE IF NOT EXISTS MaterialProducts (MaterialId INTEGER NOT NULL REFERENCES Materials(Id), ProductId INTEGER NOT NULL REFERENCES Products(Id), Quantity REAL NOT NULL CHECK(Quantity>0), PRIMARY KEY(MaterialId,ProductId));
CREATE INDEX IF NOT EXISTS IX_Materials_MaterialTypeId ON Materials(MaterialTypeId);
CREATE INDEX IF NOT EXISTS IX_Materials_UnitId ON Materials(UnitId);
CREATE INDEX IF NOT EXISTS IX_Products_ProductTypeId ON Products(ProductTypeId);
CREATE INDEX IF NOT EXISTS IX_MaterialProducts_ProductId ON MaterialProducts(ProductId);
COMMIT;

PRAGMA foreign_keys=ON;
BEGIN IMMEDIATE;
COMMIT;